oracle.query:
query open_critical_ticket_count {
  support_tickets(where: { status: { eq: "open" }, severity: { eq: "critical" } }) {
    count_id
  }
}

query active_subscription_seats {
  subscriptions(where: { status: { eq: "active" } }) {
    sum_seats
  }
}

query churn_risk_account_count {
  accounts(where: { status: { eq: "churn_risk" } }) {
    count_id
  }
}

query active_subscription_mrr {
  subscriptions(where: { status: { eq: "active" } }) {
    sum_mrr_cents
  }
}

query failed_invoice_count {
  invoices(where: { status: { eq: "failed" } }) {
    count_id
  }
}

query failed_invoice_amount {
  invoices(where: { status: { eq: "failed" } }) {
    sum_amount_cents
  }
}

query open_ticket_count {
  support_tickets(where: { status: { eq: "open" } }) {
    count_id
  }
}
